import path from 'node:path';
import { ApiError } from '../common/api-error';
import { loadConfig } from '../config';

// Server-generated by the import tool; callers never supply it.
const LOCAL_KEY = /^local:([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})$/;

// Fixtures live at <repo>/fixtures. Both src/studies (ts-node/vitest) and
// dist/studies (nest build, rootDir=src) sit exactly four levels below the repo
// root, so a fixed relative hop from __dirname is deterministic and independent
// of process.cwd().
const FIXTURES_DIR = path.resolve(__dirname, '../../../../fixtures');

export type FixtureKey = 'gradient' | 'checkerboard' | 'corrupt';

export const FIXTURE_FILES: Record<FixtureKey, string> = {
  gradient: path.join(FIXTURES_DIR, 'gradient.dcm'),
  checkerboard: path.join(FIXTURES_DIR, 'checkerboard.dcm'),
  corrupt: path.join(FIXTURES_DIR, 'corrupt.dcm'),
};

function notFound(): ApiError {
  return new ApiError(404, 'STUDY_NOT_FOUND', 'Study not found');
}

function resolveLocalFile(uuid: string): string {
  const dir = path.resolve(loadConfig().localDicomDir);
  const file = path.resolve(dir, `${uuid}.dcm`);
  // Defence in depth: the regex already forbids separators and dots.
  if (path.dirname(file) !== dir) throw notFound();
  return file;
}

/** Maps a stored fileKey to an absolute path; never builds paths from request input. */
export function resolveStudyFile(fileKey: string): string {
  const local = LOCAL_KEY.exec(fileKey);
  if (local?.[1]) return resolveLocalFile(local[1]);
  if (!Object.prototype.hasOwnProperty.call(FIXTURE_FILES, fileKey)) throw notFound();
  return FIXTURE_FILES[fileKey as FixtureKey];
}
